#include <iostream>
#include <string>

int main() {
    char choice{'n'};
    int sessionCount{0};

    do {
        ++sessionCount;
        std::cout << "Game session " << sessionCount << ": Correct number guessed!\n";
        std::cout << "Would you like to play again (y or n)? ";

        if (!(std::cin >> choice)) {
            break;
        }

        std::cout << choice << "\n";
    } while (choice == 'y' || choice == 'Y');

    std::cout << "Exiting application. Total sessions: " << sessionCount << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

struct Packet {
    int sequenceNumber;
    std::string payload;
};

int main() {
    // Simulate packets arriving out of order over a packet-switched network
    std::vector<Packet> receivedPackets = {
        {2, "World"},
        {0, "Hello"},
        {3, "Wide"},
        {1, "to"},
        {4, "Web"}
    };

    // Reassemble packets using sequencing information
    std::sort(receivedPackets.begin(), receivedPackets.end(), 
        [](const Packet& a, const Packet& b) noexcept {
            return a.sequenceNumber < b.sequenceNumber;
        }
    );

    std::cout << "Reassembled Message:";
    for (const auto& packet : receivedPackets) {
        std::cout << ' ' << packet.payload;
    }
    std::cout << '\n';

    return 0;
}
